css:
.fx-btb{display:grid;place-items:center}
.fx-btb .ph2{width:min(300px,100%);height:560px;border:8px solid var(--text);border-radius:2.2em;overflow:hidden;position:relative;background:var(--surface);box-shadow:0 24px 50px -20px color-mix(in srgb,#000 45%,transparent)}
.fx-btb .scr{height:100%;overflow:auto;padding:1.2em 1em 6.5em}
.fx-btb .scr h3{font-size:1.4em;margin-bottom:.8em}
.fx-btb .it{display:flex;gap:.8em;align-items:center;padding:.8em 0;border-bottom:1px solid var(--border);font-size:.92em}
.fx-btb .it i{width:3em;height:3em;border-radius:.8em;background:color-mix(in srgb,var(--primary) 18%,var(--surface));flex:none}
.fx-btb .it:nth-child(3n) i{background:color-mix(in srgb,var(--accent) 30%,var(--surface))}
.fx-btb .bar{position:absolute;left:.7em;right:.7em;bottom:.7em;height:4.2em;border-radius:1.4em;background:var(--primary);color:var(--on-primary);display:grid;grid-template-columns:repeat(5,1fr);align-items:center;padding:0 .2em;transition:transform calc(.35s/var(--speed)) cubic-bezier(.2,.8,.2,1);z-index:2;box-shadow:0 12px 30px -10px color-mix(in srgb,var(--primary) 70%,#000)}
.fx-btb .bar.hide{transform:translateY(130%)}
.fx-btb .pill{position:absolute;top:.5em;bottom:.5em;left:0;width:20%;padding:0 .3em;transform:translateX(var(--x,0%));transition:transform calc(.35s/var(--speed)) cubic-bezier(.3,1.3,.4,1);pointer-events:none}
.fx-btb .pill::before{content:"";display:block;height:100%;border-radius:1em;background:color-mix(in srgb,var(--on-primary) 16%,transparent)}
.fx-btb .t{position:relative;z-index:1;display:grid;justify-items:center;gap:.15em;background:none;border:0;color:inherit;font:600 .62em var(--font-body);cursor:pointer;padding:.5em 0;opacity:.7;transition:opacity calc(.2s/var(--speed))}
.fx-btb .t svg{width:2em;height:2em}.fx-btb .t[aria-current=page]{opacity:1}
.fx-btb .t.mid{opacity:1}.fx-btb .t.mid span.f{display:grid;place-items:center;width:3.4em;height:3.4em;border-radius:50%;background:var(--accent);color:var(--on-accent);margin-top:-1.6em;border:.35em solid var(--surface);box-sizing:content-box;width:2.7em;height:2.7em}
.fx-btb .t.mid svg{width:1.7em;height:1.7em}
.fx-btb .bd{position:absolute;top:.15em;right:25%;min-width:1.5em;height:1.5em;border-radius:99px;background:var(--accent);color:var(--on-accent);font:700 .85em var(--font-body);display:grid;place-items:center;padding:0 .3em}
@media(prefers-reduced-motion:reduce){.fx-btb .bar,.fx-btb .pill{transition:none}}

js:
(function(){var r=document.querySelector('.fx-btb'),sc=r.querySelector('#fx-btb-s'),bar=r.querySelector('.bar'),ts=r.querySelectorAll('.t'),pill=r.querySelector('.pill'),h=r.querySelector('#fx-btb-h'),l=r.querySelector('#fx-btb-l'),y=0;
function list(n){var h2='';for(var i=1;i<=12;i++)h2+='<div class="it"><i></i><div><b>'+n+' item '+i+'</b><br><small style="opacity:.6">Scroll to hide the bar</small></div></div>';l.innerHTML=h2}
function pick(i){ts.forEach(function(t,j){if(j===i)t.setAttribute('aria-current','page');else t.removeAttribute('aria-current')});pill.style.setProperty('--x',(i*100)+'%');var n=ts[i].dataset.n;h.textContent=n;list(n);sc.scrollTop=0;bar.classList.remove('hide')}
ts.forEach(function(t,i){t.onclick=function(){pick(i)}});
sc.addEventListener('scroll',function(){var c=sc.scrollTop;if(Math.abs(c-y)>8){bar.classList.toggle('hide',c>y&&c>60);y=c}},{passive:true});
pick(0)})();
